// Temporary replay of the pinned, already-reviewed Deep fixture; not new research.
const request = $('TEMP Deep EN Entry').first().json.body;
if (request?.authorization !== 'deep-en-interface-20261005'
    || !['ready','language_mismatch'].includes(request.scenario)) throw new Error('Explicit controlled Deep EN test required');
const manifest = $input.first().json;
const saved = manifest.nodes?.find(n => n.name === 'TEMP Deep Fixture')?.parameters?.jsCode;
if (typeof saved !== 'string') throw new Error('Saved Deep fixture missing');
const lookup = name => {
  if (name === 'TEMP Deep Entry') return {first:()=>({json:{body:{authorization:'deep-cn-interface-20261005',scenario:'ready'}}})};
  if (name === 'TEMP Deep Read Handoff') return $('TEMP Deep EN Read Handoff');
  if (name === 'TEMP Deep Read Writing') return $('TEMP Deep EN Read Writing');
  throw new Error('Unexpected fixture dependency: '+name);
};
const rows = new Function('$',saved)(lookup);
if (rows.length !== 1 || rows[0].json.decision?.story_mode !== 'deep_analysis'
    || !rows[0].json.decision.selected_candidate?.proposal?.analysis_judgment) throw new Error('Expected saved Deep judgment');
return rows;

// This invocation is a new controlled test; leave the historical fixture intact.
const w = $input.first().json, h = w.writing_input;
if (w.schema !== 'writing_work_order.v1' || w.status !== 'prepared'
    || w.story_mode !== 'deep_analysis' || w.story_id !== 'story_2') throw new Error('Prepared Deep order required');
const scenario = $('TEMP Deep EN Entry').first().json.body.scenario;
return [{json:{...w,task_config:{language:'en-US',content_type:'linkedin_article',audience:'Curious readers interested in AI'},
  writer_invocation_decision:{schema:'writer_invocation_decision.v1',status:'authorized',authorization_kind:'controlled_test',scope:'writer_draft',
    content_id:w.content_id,story_id:w.story_id,story_mode:w.story_mode,title:h.title,
    reader_promise:h.approved_story.proposal.reader_promise,target_language:scenario === 'language_mismatch' ? 'zh-CN' : 'en-US',
    decision_source:{type:'user_chat_authorization',reference:'AI_Daily:2026-10-05:continue-Deep-EN:mother_execution:'+$execution.id},side_effects_isolated:true}
},pairedItem:{item:0}}];

// Interface acceptance only. Factual and reading quality require reading the actual article.
const check = (ok,m) => {if(!ok) throw new Error('Deep EN acceptance: '+m);};
const canonical = v => JSON.stringify(v,(_,x)=>x && typeof x==='object' && !Array.isArray(x) ? Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])) : x);
const f = $('TEMP Deep EN Fixture').first().json;
const w = $('TEMP Deep EN Authorize').first().json, p = $input.first().json;
check($('TEMP Deep EN Entry').first().json.body.scenario === 'ready','negative case reached Writer return');
check(p.schema==='writing_preview.v1' && p.content_id===f.content_id && p.story_id==='story_2' && p.story_mode==='deep_analysis' && p.language==='en-US','preview identity');
check(canonical(w.writing_input.materials)===canonical(f.editor_input.materials),'material drift');
check(canonical(w.writing_input.approved_story.proposal)===canonical(f.decision.selected_candidate.proposal),'proposal drift');
check(p.config?.language==='en-US' && p.config.content_type==='linkedin_article' && p.writer_invocation_receipt?.authorization_kind==='controlled_test','metadata lost');
check(p.publication?.state==='NOT_PUBLISHED' && p.publication.url===null,'publication boundary');
check(p.status==='draft' && p.editing_status==='completed' && typeof p.draft_markdown==='string' && p.draft_markdown.trim(),'draft/edit missing');
check(typeof p.article_markdown==='string' && p.article_markdown.startsWith('# ') && !/\p{Script=Han}/u.test(p.article_markdown),'English article shape');
check(!/\b(?:initial|supplementary):(?:C|S|QT)\d+\b|writer_brief\.v3|\[Editor's Note/i.test(p.article_markdown),'internal scaffolding');
const a=p.assembled_article;
check(p.assembly_status==='completed' && a?.schema==='assembled_article.v1','assembly missing');
check(p.visual_planning_status==='completed' && p.image_generation_status==='completed','visual chain incomplete');
check(p.image_counts.requested===p.image_requests.length && p.image_counts.succeeded===p.image_requests.length && p.image_counts.failed===0,'image counts');
check(a.cover_image?.id==='COVER_IMG' && a.body_images.length===p.image_requests.filter(t=>t.role==='body_illustration').length,'dynamic body count');
let text=a.article_markdown;
for(const img of a.body_images){check(text.includes(img.markdown_insertion),'image missing');text=text.replace(img.markdown_insertion,'');}
check(text===p.article_markdown,'assembly changed prose');
check(p.image_assets.every(x=>['READY','GEOMETRY_WARNING'].includes(x.status) && /^https:\/\/raw\.githubusercontent\.com\/sztimhdd\/AI_Daily\//.test(x.asset?.url||'') && !/\p{Script=Han}/u.test(x.alt_text+x.caption)),'image destination or language');
const links=[...p.article_markdown.matchAll(/(?<!!)\[[^\]\n]+\]\((https?:\/\/[^\s)]+)\)/g)].map(m=>m[1]);
const allowed=new Set(w.writing_input.materials.sources.filter(s=>s.claim_eligible).map(s=>s.url));
check(links.length>0 && links.every(url=>allowed.has(url)),'source URL missing or invented');
return [{json:{test:'deep_en',passed:true,formal_hitl:false,
  material_counts:{sources:w.writing_input.materials.sources.length,claims:w.writing_input.materials.claims.length,quotations:w.writing_input.materials.quotations.length},
  input_judgment_preserved:true,draft_chars:p.draft_markdown.length,edited_chars:p.article_markdown.length,source_urls:[...new Set(links)],
  image_counts:p.image_counts,body_images_inserted:a.body_images.length,assembly_text_unchanged:true,
  publication:p.publication,warnings:p.warnings,article_title:a.article_title,article_markdown:a.article_markdown,cover_image:a.cover_image
},pairedItem:{item:0}}];
